CREATE DATABASE IF NOT EXISTS nexora_tumbler CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nexora_tumbler;

CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'customer',created_at DATETIME NOT NULL);
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,slug VARCHAR(190) UNIQUE NOT NULL,brand VARCHAR(80) NOT NULL,description TEXT NOT NULL,capacity VARCHAR(80) NOT NULL,material VARCHAR(120) NOT NULL,image_url TEXT NOT NULL,price BIGINT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL);
CREATE TABLE product_variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,color VARCHAR(120) NOT NULL,sku VARCHAR(80) UNIQUE NOT NULL,stock INT NOT NULL DEFAULT 0,image_url TEXT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE carts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED UNIQUE NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE cart_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,cart_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,UNIQUE KEY uq_cart_variant(cart_id,variant_id),FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE,FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE CASCADE);
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_code VARCHAR(80) UNIQUE NOT NULL,status VARCHAR(40) NOT NULL,payment_status VARCHAR(30) NOT NULL,subtotal BIGINT NOT NULL,shipping_cost BIGINT NOT NULL,total BIGINT NOT NULL,address_json TEXT NOT NULL,shipping_method VARCHAR(80) NOT NULL,payment_method VARCHAR(80) NOT NULL,tracking_number VARCHAR(120) NULL,created_at DATETIME NOT NULL,paid_at DATETIME NULL,completed_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,variant_id BIGINT UNSIGNED NOT NULL,product_name VARCHAR(190) NOT NULL,variant_name VARCHAR(120) NOT NULL,unit_price BIGINT NOT NULL,quantity INT NOT NULL,image_url TEXT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED UNIQUE NOT NULL,invoice_number VARCHAR(100) UNIQUE NOT NULL,invoice_path VARCHAR(255) NOT NULL,generated_at DATETIME NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
